function applyFrameConnBraceTurnRestriction(
  actorReference
) {
  const state =
    frameConnTurnState.current;

  if (!state) {
    return null;
  }

  const actorId =
    typeof actorReference ===
      "string"
      ? actorReference
      : actorReference?.id ??
        null;

  const actorUuid =
    typeof actorReference ===
      "object"
      ? actorReference?.uuid ??
        null
      : null;

  if (
    state.context.actorId !==
      actorId &&
    state.context.actorId !==
      actorUuid
  ) {
    return null;
  }

  const result =
    state.applyBraceRestriction();

  frameConnTurnState
    .renderApplication();

  return result;
}


