  ) {
    return this.snapshot();
  }


  this.restrictions.brace =
    true;


  this.quickActionsRemaining =
    Math.min(
      this.quickActionsRemaining,
      1
    );


  this.fullActionAvailable =
    false;


  this.movement.remaining =
